erflow: hidden;\n\tmax-height: 500px;\n}\n\n.i360-toolbar {\n\tdisplay: flex;\n\tjustify-content: flex-end;\n\talign-items: center;\n\tmin-height: 32px;\n\tmargin-top: -8px;\n\tmargin-bottom: -4px;\n}\n\n.i360-settings {\n\tpadding: 6px 8px 10px;\n\tborder-bottom: 1px solid var(--color-border);\n\n\t&__label {\n\t\tdisplay: block;\n\t\tfont-size: 11px;\n\t\ttext-transform: uppercase;\n\t\tletter-spacing: 0.4px;\n\t\tcolor: var(--color-text-maxcontrast);\n\t\tmargin-bottom: 4px;\n\t}\n}\n\n.i360-status {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 8px;\n\tpadding: 16px 8px;\n\tcolor: var(--color-text-maxcontrast);\n}\n\n.i360-rows {\n\tlist-style: none;\n\tpadding: 0;\n\tmargin: 0;\n\tdisplay: flex;\n\tflex-direction: column;\n\tmax-height: 380px;\n\toverflow-y: auto;\n\toverflow-x: hidden;\n}\n\n.i360-row {\n\tborder-radius: var(--border-radius);\n\n\t&:hover {\n\t\tbackground: var(--color-background-hover);\n\t}\n}\n\n.i360-row__link {\n\tdisplay: block;\n\tpadding: 6px 8px;\n\tcolor: inherit;\n\ttext-decoration: none;\n\tmin-width: 0;\n}\n\n.i360-row__top {\n\tdisplay: flex;\n\talign-items: center;\n\tgap: 6px;\n\tmin-width: 0;\n}\n\n.i360-row__title {\n\tflex: 1;\n\tmin-width: 0;\n\tfont-weight: 500;\n\tfont-size: 13px;\n\twhite-space: nowrap;\n\toverflow: hidden;\n\ttext-overflow: ellipsis;\n}\n\n.i360-row__meta {\n\tdisplay: flex;\n\tflex-wrap: wrap;\n\talign-items: center;\n\tgap: 4px 6px;\n\tmargin-top: 3px;\n\tfont-size: 11px;\n\tcolor: var(--color-text-maxcontrast);\n\tmin-width: 0;\n}\n\n.i360-row__meta-item {\n\twhite-space: nowrap;\n\n\t&--dim { opacity: 0.7; }\n}\n\n/*\n * Solid, high-contrast risk chips — mapped to fixed hues (green/orange/\n * red/dark-red) rather than theme variables so severity reads at a\n * glance regardless of the user's Nextcloud theme.\n */\n.i360-risk {\n\tflex-shrink: 0;\n\tdisplay: inline-block;\n\tpadding: 1px 8px;\n\tborder-radius: 10px;\n\tfont-size: 10px;\n\tfont-weight: 700;\n\tline-height: 16px;\n\ttext-transform